#!/usr/bin/env python3
"""Exact U1 header-only A/B normalization negative tests."""
import unittest
from snapmaker_u1_temporal_ab_qa import (
    header_date_only_normalization,compare_temporally_separated,
)

def example(time="00:00:00",command="G1 X10 Y10"):
    return ("; HEADER_BLOCK_START\n"
            "; generated by Snapmaker Orca 2.4.1 on 2026-11-07 at "+time+"\n"
            "; total layer number: 100\n"
            "; HEADER_BLOCK_END\n"
            +command+"\n").encode()

class TestTemporalProof(unittest.TestCase):
    def test_only_header_timestamp_may_change(self):
        proof=compare_temporally_separated(example("00:00:01"),example("00:00:04"))
        self.assertTrue(proof["all_other_bytes_equal"])
        self.assertFalse(proof["raw_equal"])
        self.assertEqual(proof["A"]["line_number"],2)
        self.assertEqual(proof["A"]["normalized_sha256"],proof["B"]["normalized_sha256"])

    def test_print_path_change_rejected_even_if_timestamps_differ(self):
        with self.assertRaisesRegex(ValueError,"NON_TIMESTAMP_GCODE_DIFFERENCE"):
            compare_temporally_separated(example("00:00:01","G1 X10"),
                                         example("00:00:04","G1 X11"))

    def test_same_second_is_not_valid_temporal_control(self):
        with self.assertRaisesRegex(ValueError,"SAME_SECOND_NOT_A_VALID_TEMPORAL_AB"):
            compare_temporally_separated(example("00:00:01"),example("00:00:01"))

    def test_missing_timestamp_rejected(self):
        with self.assertRaisesRegex(ValueError,"EXACTLY_ONE_OFFICIAL_TIMESTAMP_LINE_REQUIRED"):
            header_date_only_normalization(
                example().replace(b"; generated by Snapmaker Orca 2.4.1 on 2026-11-07 at 00:00:00\n",b""))

    def test_unrecognized_weak_timestamp_rejected(self):
        with self.assertRaisesRegex(ValueError,"EXACTLY_ONE_OFFICIAL_TIMESTAMP_LINE_REQUIRED"):
            header_date_only_normalization(
                example().replace(b"Snapmaker Orca 2.4.1",b"Unknown OEM 2.4.1"))

    def test_timestamp_outside_header_rejected(self):
        t=example().replace(b"; generated by Snapmaker Orca 2.4.1 on 2026-11-07 at 00:00:00\n",b"")
        t+=b"; generated by Snapmaker Orca 2.4.1 on 2026-11-07 at 00:00:00\n"
        with self.assertRaisesRegex(ValueError,"EXACTLY_ONE_OFFICIAL_TIMESTAMP_LINE_REQUIRED"):
            header_date_only_normalization(t)


if __name__=="__main__":
    unittest.main()
